public class BufferPoolTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static String idOf(Buffer b) {
        return b == null ? "null" : String.valueOf(b.id());
    }

    public static void main(String[] args) {
        check("first acquire has id 1", "1",
                safe(() -> idOf(new BufferPool(2).acquire())));
        check("two acquires get different objects", "1|2|2|0|2",
                safe(() -> {
                    BufferPool pool = new BufferPool(2);
                    Buffer a = pool.acquire();
                    Buffer b = pool.acquire();
                    return idOf(a) + "|" + idOf(b) + "|" + pool.liveCount()
                            + "|" + pool.freeCount() + "|" + pool.createdCount();
                }));
        check("an exhausted pool hands back null", "null",
                safe(() -> {
                    BufferPool pool = new BufferPool(2);
                    pool.acquire();
                    pool.acquire();
                    return idOf(pool.acquire());
                }));
        check("release moves a buffer from live to free", "true|1|1",
                safe(() -> {
                    BufferPool pool = new BufferPool(2);
                    Buffer a = pool.acquire();
                    pool.acquire();
                    boolean ok = pool.release(a);
                    return ok + "|" + pool.liveCount() + "|" + pool.freeCount();
                }));
        check("a released buffer is reused, not re-created", "1|2",
                safe(() -> {
                    BufferPool pool = new BufferPool(2);
                    Buffer a = pool.acquire();
                    pool.acquire();
                    pool.release(a);
                    Buffer again = pool.acquire();
                    return idOf(again) + "|" + pool.createdCount();
                }));
        check("a reused buffer comes back empty", "",
                safe(() -> {
                    BufferPool pool = new BufferPool(1);
                    Buffer a = pool.acquire();
                    a.write("stale data");
                    pool.release(a);
                    return pool.acquire().contents();
                }));
        check("double release is refused", "false|0|1",
                safe(() -> {
                    BufferPool pool = new BufferPool(2);
                    Buffer a = pool.acquire();
                    pool.release(a);
                    boolean second = pool.release(a);
                    return second + "|" + pool.liveCount() + "|" + pool.freeCount();
                }));
        check("releasing null is refused", Boolean.FALSE,
                safe(() -> new BufferPool(2).release(null)));
        check("a stranger from another pool is refused", "false|0",
                safe(() -> {
                    BufferPool one = new BufferPool(2);
                    BufferPool two = new BufferPool(2);
                    Buffer alien = one.acquire();
                    boolean ok = two.release(alien);
                    return ok + "|" + two.freeCount();
                }));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

