public class BufferPool {

    private final int capacity;
    private final java.util.List<Buffer> free = new java.util.ArrayList<>();
    private final java.util.List<Buffer> live = new java.util.ArrayList<>();
    private int created = 0;

    public BufferPool(int capacity) {
        this.capacity = capacity;
    }

    public int getCapacity() {
        return capacity;
    }

    public int createdCount() {
        return created;
    }

    public int liveCount() {
        return live.size();
    }

    public int freeCount() {
        return free.size();
    }

    public Buffer acquire() {
        Buffer buffer;
        if (!free.isEmpty()) {
            buffer = free.remove(free.size() - 1);
            buffer.reset();
        } else if (created < capacity) {
            created++;
            buffer = new Buffer(created);
        } else {
            return null;
        }
        live.add(buffer);
        return buffer;
    }

    public boolean release(Buffer buffer) {
        if (buffer == null) {
            return false;
        }
        for (int i = 0; i < live.size(); i++) {
            if (live.get(i) == buffer) {
                live.remove(i);
                free.add(buffer);
                return true;
            }
        }
        return false;
    }
}
